// El portal manda el archivo en base64 cuando no tiene el texto (PDF sin lectura previa). n8n extrae el texto del PDF.
const d = $input.first().json;
if (!d.cv || !d.cv.base64) throw new Error('El portal no envió ni el texto ni el archivo del CV');
if (!/pdf/i.test(d.cv.mime || '') && !/\.pdf$/i.test(d.cv.nombre || '')) throw new Error('El CV no es PDF y no tiene texto leído: usa «Cargar CV» (lo lee el OCR) o pide un PDF o un Word');
return [{ json: {}, binary: { data: { data: d.cv.base64, mimeType: 'application/pdf', fileName: d.cv.nombre || 'cv.pdf' } } }];

// El prompt lo arma el PORTAL (reglas firmes + instrucciones de Gestión Humana + datos y formato). Aquí solo se pone el CV
// (tachado de datos protegidos) en su marca y se arma la petición al modelo local, con la API compatible con OpenAI.
const MODELO = 'REEMPLAZAR-nombre-del-modelo';   // p. ej. qwen2.5:14b (Ollama), el nombre que use tu servidor
const JSON_MODE = true;                          // false si tu servidor no acepta response_format
const ET = 'fecha\\s+de\\s+nacimiento|lugar\\s+de\\s+nacimiento|nacimiento|edad|estado\\s+civil|sexo|g[eé]nero|nacionalidad|religi[oó]n|salud|discapacidad|embarazo|hijos|c[eé]dula(?:\\s+de\\s+identidad)?|c\\.\\s?i\\.?|peso|estatura|grupo\\s+sangu[ií]neo';
const redactar = t => String(t || '')
  .replace(new RegExp('^\\s*(?:' + ET + ')\\s*[:：-].*$', 'gim'), '[dato personal omitido]')
  .replace(new RegExp('\\b(?:' + ET + ')\\s*[:：]\\s*[^\\n;|]+', 'gi'), '[dato personal omitido]')
  .replace(/\b\d{2}\s+años\s+de\s+edad\b/gi, '[dato personal omitido]')
  .replace(/\b(solter[oa]|casad[oa]|divorciad[oa]|viud[oa]|concubin[oa])\b/gi, '[omitido]');
const d = $('Leer datos del portal').first().json;
if (!d.prompt || !d.prompt.sistema || !d.prompt.usuario) throw new Error('El portal no envió el prompt: actualiza el portal a la 0.9.5 o superior');
let usuario = d.prompt.usuario, texto_cv = null;
if (d.tipo !== 'resumen') {
  const extraido = !(d.cv && d.cv.texto);
  let texto = extraido ? String($input.first().json.text || '') : d.cv.texto;
  texto = redactar(texto).replace(/\u0000/g, '').slice(0, 40000);
  if (texto.replace(/\s+/g, '').length < 80) throw new Error('El CV no tiene texto legible (¿PDF escaneado como imagen?). Usa «Cargar CV» para leerlo con OCR o pide un PDF con texto');
  usuario = usuario.split(d.prompt.marca_cv || '<<CV>>').join(texto);   // split/join: el texto del CV no se interpreta
  if (extraido) texto_cv = texto;
}
const peticion = { model: MODELO, temperature: 0.2, messages: [{ role: 'system', content: d.prompt.sistema }, { role: 'user', content: usuario }],
  ...(JSON_MODE ? { response_format: { type: 'json_object' } } : {}) };
return [{ json: { peticion, modelo: MODELO, texto_cv } }];

// Toma el JSON que devolvió el modelo. El portal valida el contenido (criterios, puntajes, terna) y responde 400 si algo falta.
const a = $('Armar petición al modelo').first().json, r = $input.first().json;
const msg = (r.choices && r.choices[0] && r.choices[0].message) || r.message || {};
let raw = String(msg.content || r.response || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
const i = raw.indexOf('{'), j = raw.lastIndexOf('}');
if (i < 0 || j < i) throw new Error('El modelo no devolvió JSON');
let respuesta; try { respuesta = JSON.parse(raw.slice(i, j + 1)); } catch (e) { throw new Error('El modelo devolvió un JSON inválido: ' + e.message); }
return [{ json: { respuesta, modelo: a.modelo, ...(a.texto_cv ? { texto_cv: a.texto_cv } : {}) } }];
